function analyzeNewsSentiment() {
  function nodeRaw(name) {
    try {
      const j = $(name).first().json || {};
      if (typeof j === "string") return j;
      if (typeof j.data === "string") return j.data;
      if (typeof j.body === "string") return j.body;
      if (typeof j.response === "string") return j.response;
      return JSON.stringify(j);
    } catch (e) {
      return "";
    }
  }

  function decode(s) {
    return String(s || "")
      .replace(/<!\[CDATA\[/g, "")
      .replace(/\]\]>/g, "")
      .replace(/&amp;/g, "&")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">");
  }

  function titlesFromXml(xml) {
    const text = decode(xml);
    const out = [];
    const re = /<title[^>]*>([\s\S]*?)<\/title>/gi;
    let m;
    while ((m = re.exec(text)) !== null) {
      const title = decode(m[1]).replace(/<[^>]+>/g, "").trim();
      if (title && title.length > 8 && !/cointelegraph|coindesk/i.test(title)) out.push(title);
      if (out.length >= 20) break;
    }
    return out;
  }

  const titles = [
    ...titlesFromXml(nodeRaw("Fetch Cointelegraph News HTTP")),
    ...titlesFromXml(nodeRaw("Fetch CoinDesk News HTTP"))
  ].filter((v, i, a) => v && a.indexOf(v) === i).slice(0, 25);

  const btcTitles = titles.filter(t => {
    const x = t.toLowerCase();
    return x.includes("bitcoin") || x.includes("btc") || x.includes("crypto") || x.includes("etf") || x.includes("fed") || x.includes("binance");
  });

  let score = 0, risk = 0;
  const bullish = ["inflow","inflows","blackrock","accumulate","bullish","rally","surge","breakout","institutional","adoption","approved","approval","rate cut","dovish","record high","buys"];
  const bearish = ["outflow","outflows","sell-off","selloff","crash","plunge","drop","bearish","liquidation","liquidations","lawsuit","sec","ban","hack","exploit","fraud","probe","investigation","regulation","hawkish","rate hike","falls","slump"];
  const highRisk = ["hack","exploit","lawsuit","sec","ban","fraud","liquidation","liquidations","crash","probe","investigation","bankruptcy"];

  for (const title of btcTitles) {
    const x = title.toLowerCase();
    for (const w of bullish) if (x.includes(w)) score += 4;
    for (const w of bearish) if (x.includes(w)) score -= 4;
    for (const w of highRisk) if (x.includes(w)) risk += 1;
  }

  score = Math.max(-30, Math.min(30, score));

  let sentiment = "NEUTRAL";
  if (score >= 12) sentiment = "BULLISH";
  if (score <= -12) sentiment = "BEARISH";
  if (risk >= 2) sentiment = "HIGH_RISK";
  if (titles.length === 0) sentiment = "NO_NEWS";
  else if (btcTitles.length === 0) sentiment = "NO_BTC_NEWS";

  return {
    newsScore: score,
    newsSentiment: sentiment,
    newsRiskCount: risk,
    newsItemsCount: btcTitles.length,
    newsTotalTitles: titles.length,
    topNews: btcTitles.slice(0, 3)
  };
}

function getKlines() {
  const first = $input.first().json;
  if (Array.isArray(first) && Array.isArray(first[0])) return first;
  if (Array.isArray(first) && first.length >= 6) {
    return $input.all().map(i => i.json).filter(k => Array.isArray(k) && k.length >= 6);
  }
  return [];
}

function aggregate(klines, group) {
  const out = [];
  for (let i = 0; i + group <= klines.length; i += group) {
    const c = klines.slice(i, i + group);
    out.push([
      c[0][0],
      c[0][1],
      Math.max(...c.map(x => Number(x[2]))).toString(),
      Math.min(...c.map(x => Number(x[3]))).toString(),
      c[c.length - 1][4],
      c.reduce((s, x) => s + Number(x[5]), 0).toString()
    ]);
  }
  return out;
}

function nums(klines, idx) {
  return klines.map(k => Number(k[idx])).filter(Number.isFinite);
}

function ema(arr, p) {
  if (!arr.length) return 0;
  const k = 2 / (p + 1);
  let e = arr[0];
  for (let i = 1; i < arr.length; i++) e = arr[i] * k + e * (1 - k);
  return e;
}

function sma(arr, p) {
  const s = arr.slice(-p);
  return s.reduce((a,b)=>a+b,0) / Math.max(1, s.length);
}

function rsi(arr, p = 14) {
  if (arr.length <= p + 1) return 50;
  let gains = 0, losses = 0;
  for (let i = arr.length - p; i < arr.length - 1; i++) {
    const d = arr[i + 1] - arr[i];
    if (d > 0) gains += d; else losses -= d;
  }
  const avgGain = gains / p;
  const avgLoss = losses / p || 0.000001;
  const rs = avgGain / avgLoss;
  return 100 - (100 / (1 + rs));
}

function atr(highs, lows, closes, p = 14) {
  if (closes.length <= p + 1) return 0;
  const trs = [];
  for (let i = 1; i < closes.length; i++) {
    trs.push(Math.max(
      highs[i] - lows[i],
      Math.abs(highs[i] - closes[i-1]),
      Math.abs(lows[i] - closes[i-1])
    ));
  }
  const s = trs.slice(-p);
  return s.reduce((a,b)=>a+b,0) / Math.max(1, s.length);
}

function trend(closes) {
  if (closes.length < 30) return "UNKNOWN";
  const e9 = ema(closes, 9);
  const e21 = ema(closes, 21);
  const e50 = closes.length >= 50 ? ema(closes, 50) : ema(closes, Math.max(10, Math.floor(closes.length / 2)));
  if (e9 > e21 && e21 > e50) return "BULLISH";
  if (e9 < e21 && e21 < e50) return "BEARISH";
  return "SIDEWAYS";
}

const klines15 = getKlines();

if (klines15.length < 100) {
  return [{ json: {
    canAnalyze: false,
    action: "HOLD",
    price: "NO_DATA",
    rsi: "N/A",
