  }}];
}

// No extra network requests.
// 1h = 4 x 15m, 2h = 8 x 15m, 4h = 16 x 15m
const klines1h = aggregate(klines15, 4);
const klines2h = aggregate(klines15, 8);
const klines4h = aggregate(klines15, 16);

const closes15 = nums(klines15, 4);
const highs15 = nums(klines15, 2);
const lows15 = nums(klines15, 3);
const volumes15 = nums(klines15, 5);

const closes1h = nums(klines1h, 4);
const closes2h = nums(klines2h, 4);
const closes4h = nums(klines4h, 4);

const price = closes15.at(-1);
const rsi14 = rsi(closes15);
const trend15m = trend(closes15);
const trend1h = trend(closes1h);
const trend2h = trend(closes2h);
const trend4h = trend(closes4h);

const ema9 = ema(closes15, 9);
const ema21 = ema(closes15, 21);
const macd = ema(closes15, 12) - ema(closes15, 26);
const a = atr(highs15, lows15, closes15, 14);
const volatility = (a / price) * 100;
const volRatio = volumes15.at(-1) / (sma(volumes15, 50) || 1);
const news = analyzeNewsSentiment();

let longScore = 50;
let shortScore = 50;

// Correct directional scoring.
// Bullish trend increases LONG and decreases SHORT.
if (trend15m === "BULLISH") { longScore += 8; shortScore -= 8; }
if (trend1h === "BULLISH") { longScore += 12; shortScore -= 12; }
if (trend2h === "BULLISH") { longScore += 16; shortScore -= 16; }
if (trend4h === "BULLISH") { longScore += 18; shortScore -= 18; }

// Bearish trend increases SHORT and decreases LONG.
if (trend15m === "BEARISH") { shortScore += 8; longScore -= 8; }
if (trend1h === "BEARISH") { shortScore += 12; longScore -= 12; }
if (trend2h === "BEARISH") { shortScore += 16; longScore -= 16; }
if (trend4h === "BEARISH") { shortScore += 18; longScore -= 18; }

// Momentum confirmation.
if (price > ema9 && ema9 > ema21) { longScore += 10; shortScore -= 6; }
if (price < ema9 && ema9 < ema21) { shortScore += 10; longScore -= 6; }

if (macd > 0) { longScore += 8; shortScore -= 6; }
if (macd < 0) { shortScore += 8; longScore -= 6; }

// RSI zones.
if (rsi14 >= 38 && rsi14 <= 72) longScore += 6;
if (rsi14 >= 30 && rsi14 <= 58) shortScore += 6;

// Market quality.
if (volRatio > 1) { longScore += 4; shortScore += 4; }
if (volRatio < 0.7) { longScore -= 5; shortScore -= 5; }
if (volatility < 0.08) { longScore -= 10; shortScore -= 10; }
if (volatility > 4) { longScore -= 15; shortScore -= 15; }

// RSS news adjustment spot
if (news.newsSentiment === "BULLISH") longScore += Math.max(5, Math.round(news.newsScore / 2));
if (news.newsSentiment === "BEARISH") longScore -= Math.max(10, Math.abs(news.newsScore));
if (news.newsSentiment === "HIGH_RISK") longScore -= 25;

longScore = Math.max(0, Math.min(100, Math.round(longScore)));
shortScore = Math.max(0, Math.min(100, Math.round(shortScore)));

let signal = "HOLD";
let reason = "No quality setup";

// LONG when longScore dominates.
if (
  longScore >= 45 &&
