function prettyDateTime(ts) {
  if (!ts) return 'N/A';
  const d = new Date(new Date(ts).getTime() + 3 * 60 * 60 * 1000);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  const h = String(d.getUTCHours()).padStart(2, '0');
  const min = String(d.getUTCMinutes()).padStart(2, '0');
  const s = String(d.getUTCSeconds()).padStart(2, '0');
  return `${y}-${m}-${day}  ${h}:${min}м ${s}с`;
}

function chooseCooldownMinutes(market, cfg) {
  const longScore = Number(market.longScore || market.signalScore || 0);
  const shortScore = Number(market.shortScore || 0);
  const signalScore = Math.max(longScore, shortScore);
  const spread = Math.abs(longScore - shortScore);
  const vol = Number(market.volatilityPercent || 0);
  const vr = Number(market.volumeRatio || 1);
  const strongTrend = signalScore >= 90 && spread >= 50 && ((market.trend1h === 'BEARISH' && market.trend2h === 'BEARISH') || (market.trend1h === 'BULLISH' && market.trend2h === 'BULLISH'));
  const normalTrend = signalScore >= 70 && spread >= 25 && market.trend1h !== 'SIDEWAYS' && market.trend2h !== 'SIDEWAYS';
  const sideways = market.trend1h === 'SIDEWAYS' || market.trend2h === 'SIDEWAYS' || spread < 20 || signalScore < 60;
  let cd = Number(cfg.cooldownMin || 25);
  if (strongTrend) cd = 5;
  else if (normalTrend) cd = 10;
  else if (sideways) cd = 45;
  else cd = 20;
  if (vol >= 2.0) cd = Math.max(cd, 20);
  if (vr < 0.8) cd = Math.max(cd, 30);
  return Math.max(5, Math.min(60, cd));
}


function chooseHoldMinutes(market, cfg) {
  const score = Number(market.signalScore || 0);
  const vol = Number(market.volatilityPercent || 0);
  const vr = Number(market.volumeRatio || 1);

  let hold = 30;

  if (score >= 80) hold = 120;
  else if (score >= 70) hold = 90;
  else if (score >= 60) hold = 60;
  else if (score >= 50) hold = 30;
  else hold = 15;

  if (vol >= 1.2) hold = Math.min(hold, 45);
  if (vol >= 2.0) hold = Math.min(hold, 30);
  if (vr < 0.8) hold = Math.min(hold, 30);

  hold = Math.max(cfg.minHoldMin || 15, Math.min(cfg.maxHoldMin || 120, hold));
  return Math.max(15, Math.min(120, hold));
}
