  orderSide = 'SELL';
  positionAction = 'CLOSE_LONG';
}

if (position.side === 'FLAT' && desired === 'SELL') {
  action = 'HOLD';
  orderSide = 'HOLD';
  positionAction = 'NONE';
  reason = 'Bearish market detected. Waiting for LONG setup.';
}

// Auto close by time.
if (position.side !== 'FLAT' && position.closeAt && now >= new Date(position.closeAt).getTime()) {
  if (position.side === 'LONG') {
    action = 'SELL';
    orderSide = 'SELL';
    positionAction = 'CLOSE_LONG';
    reason = 'Timed exit LONG';
  }
  if (position.side === 'SHORT') {
    action = 'COVER';
    orderSide = 'BUY';
    positionAction = 'CLOSE_SHORT';
    reason = 'Timed exit SHORT';
  }
}

// SL/TP protection.
if (position.side === 'LONG') {
  if (position.stopLoss && Number(market.price) <= position.stopLoss) { action = 'SELL'; orderSide = 'SELL'; positionAction = 'CLOSE_LONG'; reason = 'LONG stop loss hit'; }
  if (position.takeProfit && Number(market.price) >= position.takeProfit) { action = 'SELL'; orderSide = 'SELL'; positionAction = 'CLOSE_LONG'; reason = 'LONG take profit hit'; }
}
if (position.side === 'SHORT') {
  if (position.stopLoss && Number(market.price) >= position.stopLoss) { action = 'COVER'; orderSide = 'BUY'; positionAction = 'CLOSE_SHORT'; reason = 'SHORT stop loss hit'; }
  if (position.takeProfit && Number(market.price) <= position.takeProfit) { action = 'COVER'; orderSide = 'BUY'; positionAction = 'CLOSE_SHORT'; reason = 'SHORT take profit hit'; }
}

const dynamicCooldownMin = chooseCooldownMinutes(market, cfg);
const lastTradeTs = Number(state.lastPaperTradeAt || state.lastTradeAt || 0);
const cooldownStartTs = lastTradeTs || 0;
const cooldownEndTs = cooldownStartTs ? cooldownStartTs + dynamicCooldownMin * 60 * 1000 : 0;

let block = '';

if (state.paused) block = 'Bot paused';
if (!market.canAnalyze) block = market.reason || 'Market data unavailable';

if (positionAction === 'OPEN_LONG' && Number(market.longScore || 0) < cfg.minScore) {
  block = `LONG score too low: ${market.longScore}% < ${cfg.minScore}%`;
}
if (positionAction === 'OPEN_SHORT' && Number(market.shortScore || 0) < cfg.minScore) {
  block = `SHORT score too low: ${market.shortScore}% < ${cfg.minScore}%`;
}

if (positionAction === 'OPEN_SHORT' && !isFutures) {
  block = 'Strong SHORT signal, but SPOT mode cannot open SHORT';
}

if (positionAction === 'OPEN_LONG' && position.side !== 'FLAT') block = 'Already in position';
if (positionAction === 'OPEN_SHORT' && position.side !== 'FLAT') block = 'Already in position';
if (positionAction === 'CLOSE_LONG' && position.side !== 'LONG') block = 'No LONG position to close';
if (positionAction === 'CLOSE_SHORT' && position.side !== 'SHORT') block = 'No SHORT position to close';

