let qs = `symbol=${symbol}&side=${orderSide}&type=MARKET&quantity=${qty}&timestamp=${timestamp}&recvWindow=${recvWindow}`;


const signature = crypto.createHmac('sha256', secret).update(qs).digest('hex');
const finalUrl = `${endpoint}?${qs}&signature=${signature}`;

let stopLoss = '';
let takeProfit = '';
let closeAt = '';

if (positionAction === 'OPEN_LONG') {
  stopLoss = Number((Number(market.price) - Number(market.atr || 0) * 1.1).toFixed(2));
  takeProfit = Number((Number(market.price) + Number(market.atr || 0) * 2.4).toFixed(2));
  const holdMinutes = chooseHoldMinutes(market, cfg);
  closeAt = new Date(now + holdMinutes * 60 * 1000).toISOString();
  state.position = { side: 'LONG', entry: Number(market.price), qty, stopLoss, takeProfit, closeAt,
    plannedCloseAt: closeAt ? prettyDateTime(closeAt) : 'N/A', venue: 'SPOT_TESTNET', leverage: isFutures ? cfg.leverage : 1 };
}

if (positionAction === 'OPEN_SHORT') {
  stopLoss = Number((Number(market.price) + Number(market.atr || 0) * 1.1).toFixed(2));
  takeProfit = Number((Number(market.price) - Number(market.atr || 0) * 2.4).toFixed(2));
  const holdMinutes = chooseHoldMinutes(market, cfg);
  closeAt = new Date(now + holdMinutes * 60 * 1000).toISOString();
  state.position = { side: 'SHORT', entry: Number(market.price), qty, stopLoss, takeProfit, closeAt, venue: 'SPOT_TESTNET', leverage: cfg.leverage };
}

if (['CLOSE_LONG','CLOSE_SHORT'].includes(positionAction) && position.side !== 'FLAT') {
  if (pnl >= 0) state.stats.wins += 1;
  else { state.stats.losses += 1; state.lastLossAt = now; }
  state.stats.trades += 1;
  state.stats.pnl = Number((Number(state.stats.pnl || 0) + pnl).toFixed(4));
  state.position = { side: 'FLAT', entry: 0, qty: 0 };
}

state.lastTradeAt = now;

return [{
  json: {
    ...base,
    canTrade: true,
    action,
    orderSide,
    positionAction,
    reason,
    quantity: qty,
    entry: ['OPEN_LONG','OPEN_SHORT'].includes(positionAction) ? market.price : position.entry,
    exitPrice: ['CLOSE_LONG','CLOSE_SHORT'].includes(positionAction) ? market.price : '',
    stopLoss,
    takeProfit,
    closeAt,
    holdMinutes: typeof holdMinutes !== 'undefined' ? holdMinutes : (position.holdMinutes || ''),
    finalUrl,
    apiKey,
    pnl: Number(pnl.toFixed(4))
