function prettyTime() {
  const d = new Date(Date.now() + 3 * 60 * 60 * 1000);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  const h = String(d.getUTCHours()).padStart(2, '0');
  const min = String(d.getUTCMinutes()).padStart(2, '0');
  const s = String(d.getUTCSeconds()).padStart(2, '0');
  return `${y}-${m}-${day}  ${h}:${min}м ${s}с`;
}

const input = $input.first().json || {};
const body = input.body || input;
const cb = body.callback_query;
const state = $getWorkflowStaticData('global');

if (!state.mode) state.mode = 'ACTIVE';
state.venue = 'SPOT_TESTNET';
if (typeof state.paused !== 'boolean') state.paused = false;
if (!state.position) state.position = { side: 'FLAT', entry: 0, qty: 0 };
if (!state.stats) state.stats = { trades: 0, wins: 0, losses: 0, pnl: 0, errors: 0, lastError: '' };

if (!cb) {
  return [{ json: { callbackId: '', text: 'No callback_query received' } }];
}

const data = cb.data || '';
let text = '';

const trades = Number(state.stats.trades || 0);
const wins = Number(state.stats.wins || 0);
const losses = Number(state.stats.losses || 0);
const winrate = trades > 0 ? ((wins / trades) * 100).toFixed(2) : '0.00';

if (data === 'PAUSE') {
  state.paused = true;
  text = `⏸️ Spot bot paused\n\nTime: ${prettyTime()}`;
}

else if (data === 'RESUME') {
  state.paused = false;
  text = `▶️ Spot bot resumed\n\nTime: ${prettyTime()}`;
}

else if (data === 'MODE_SAFE') {
  state.mode = 'SAFE';
  text = `🛡️ Mode changed to SAFE\n\nMin Score: 75+\nStyle: conservative\nTime: ${prettyTime()}`;
}

else if (data === 'MODE_ACTIVE') {
  state.mode = 'ACTIVE';
  text = `⚙️ Mode changed to ACTIVE\n\nMin Score: 55+\nStyle: balanced\nTime: ${prettyTime()}`;
}

else if (data === 'MODE_AGGRESSIVE') {
  state.mode = 'AGGRESSIVE';
  text = `🔥 Mode changed to AGGRESSIVE\n\nMin Score: 45+\nStyle: more entries\nTime: ${prettyTime()}`;
}

else if (data === 'RESET_STATS') {
  state.stats = { trades: 0, wins: 0, losses: 0, pnl: 0, errors: 0, lastError: '' };
  state.position = { side: 'FLAT', entry: 0, qty: 0 };
  state.lastTradeAt = 0;
  state.lastLossAt = 0;
  text = `♻️ Spot stats reset\n\nPosition reset to FLAT\nTime: ${prettyTime()}`;
}

else if (data === 'LAST_ERROR') {
  text =
`🧾 LAST ERROR

Errors: ${state.stats.errors || 0}
Last Error:
${state.stats.lastError || 'No stored error'}

Time: ${prettyTime()}`;
}

else if (data === 'BALANCE') {
  text =
`💰 SPOT TEST STATUS

This is internal bot accounting, not real Binance wallet balance.

Position: ${state.position.side || 'FLAT'}
Qty: ${state.position.qty || 0} BTC
Entry: $${state.position.entry || 0}

Current Bot PnL: $${state.stats.pnl || 0}
Trades Closed: ${trades}
Wins/Losses: ${wins}/${losses}
Winrate: ${winrate}%

Time: ${prettyTime()}`;
}

else if (data === 'STATUS') {
  text =
`📊 SPOT BOT STATUS

Mode: ${state.mode}
Venue: SPOT_TESTNET
Paused: ${state.paused}

Position: ${state.position.side || 'FLAT'}
Entry: $${state.position.entry || 0}
Qty: ${state.position.qty || 0} BTC
Stop Loss: ${state.position.stopLoss || 'N/A'}
Take Profit: ${state.position.takeProfit || 'N/A'}
Planned Close: ${state.position.closeAt || 'N/A'}

Last Trade At: ${state.lastTradeAt ? new Date(state.lastTradeAt).toISOString() : 'N/A'}
Errors: ${state.stats.errors || 0}

Time: ${prettyTime()}`;
}

else {
  text = `Unknown command: ${data}\n\nTime: ${prettyTime()}`;
}

return [{
  json: {
    callbackId: cb.id || '',
    text
  }
}];

